declare(strict_types=1);
$db=db_read();if(!$db){http_response_code(503);exit('Форум ещё не установлен');}
$me=current_user($db);$p=(string)($_GET['p']??'home');$pid=arg('id');
$pages=['home','board','thread','new','login','register','account','profile','search','notifications','bookmarks','admin','reports','rules'];
if(!in_array($p,$pages,true)){$p='notfound';http_response_code(404);}
function setting_f(string $key): string {global $db;return (string)($db['settings'][$key]??'');}
function navclass(string $route): string {global $p;return $p===$route?'selected':'';}
function section_title(string $h,string $desc=''): void {echo '<div class="section-title"><div><h2>'.h($h).'</h2>'.($desc?'<p>'.h($desc).'</p>':'').'</div></div>';}
function avatar(array $u,string $size=''): string { $c=cut($u['username']??'V',1);return '<div class="avatar '.h($size).'">'.h(strtoupper($c)).'</div>'; }
function author_link(int $id): string {global $db;return '<a href="'.h(link_to('profile',['id'=>$id])).'">'.h(user_name($db,$id)).'</a>';}
function role_badge(string $role): string {return '<span class="role '.h($role).'">'.h(role_label($role)).'</span>';}
function stat_count(): array {global $db,$me;return [count($db['users']),count(array_filter($db['threads'],fn($t)=>thread_visible($db,$t,$me))),count(array_filter($db['posts'],fn($p)=>empty($p['deleted']) && ($t=findrow($db['threads'],(int)$p['thread_id'])) && thread_visible($db,$t,$me)))];}
function list_thread(array $t): void {
  global $db,$me;
  $author=findrow($db['users'],(int)$t['author_id'])??['username'=>'?'];
  $pc=count(topic_posts($db,(int)$t['id']));$dest=link_to('thread',['id'=>$t['id']]);
  echo '<article class="thread-row"><div class="thread-symbol">'.($t['pinned']?'✦':'#').'</div><div class="thread-primary"><a class="thread-name" href="'.h($dest).'">'.h($t['title']).'</a><div class="thread-meta">'.($t['pinned']?'<span class="tag highlight">Закреплено</span> ':'').($t['locked']?'<span class="tag">Закрыто</span> ':'').($t['deleted']?'<span class="tag danger">Скрыто</span> ':'').author_link((int)$t['author_id']).' · '.human_date((int)$t['created']).'</div></div><div class="thread-numbers"><b>'.max(0,$pc-1).'</b><span>ответов</span></div><div class="thread-last"><b>'.h(user_name($db,(int)$t['last_author_id'])).'</b><span>'.human_date((int)$t['updated']).'</span></div></article>';
}
function form_start(string $action,string $page='home',int $id=0): void {echo '<form method="post" class="form">'.field_csrf().'<input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="_page" value="'.h($page).'"><input type="hidden" name="_id" value="'.$id.'">';}
function form_end(string $label='Сохранить',string $class='btn accent'): void {echo '<button type="submit" class="'.h($class).'">'.h($label).'</button></form>';}
function board_thread_rows(array $rows): void {if(!$rows){echo '<div class="empty-state"><span>✦</span><h3>Здесь пока нет тем</h3><p>Начните первое обсуждение в этом разделе.</p></div>';return;}foreach($rows as $t)list_thread($t);}
function pagination(int $page,int $pages,string $route,array $args=[]): void {
 if($pages<2)return;echo '<div class="pagination">';for($i=1;$i<=$pages;$i++){
   if($i>1 && $i<$pages && abs($i-$page)>2)continue;
   echo '<a class="'.($i===$page?'active':'').'" href="'.h(link_to($route,$args+['page'=>$i])).'">'.$i.'</a>';
 }echo '</div>';
}
